{
  "name": "oh-my-openspec",
  "version": "1.17.0",
  "description": "OpenSpec multi-agent flow for OpenCode: /omos.plan drafts a change through research and critique, /omos.apply implements tasks.md through dependency-ordered parallel subagent waves with mechanical openspec CLI validation",
  "keywords": [
    "agents",
    "opencode",
    "opencode-plugin",
    "openspec",
    "skills",
    "spec-driven-development",
    "workflow"
  ],
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": "./opencode/index.ts"
  },
  "files": [
    "agents",
    "core",
    "docs",
    "opencode",
    "skills",
    "vendor",
    "index.ts",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test \"tests/**/*.test.ts\"",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.28",
    "yaml": "^2"
  },
  "devDependencies": {
    "@fission-ai/openspec": "^1.17.0",
    "@types/node": "^26",
    "typescript": "^7.0.2"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alexeyco/oh-my-openspec.git"
  },
  "homepage": "https://github.com/alexeyco/oh-my-openspec",
  "bugs": "https://github.com/alexeyco/oh-my-openspec/issues",
  "author": {
    "name": "Alexeyco",
    "url": "https://github.com/alexeyco"
  },
  "engines": {
    "node": ">=22.18"
  }
}
